with unpacked as (select id, plan, effective_from, currency, slice(tier_limits, 1, 2) as first_two_limits, aggregate(tier_prices, 0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, array_min(tier_prices) as lowest_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, element_at(tier_prices, 1) as entry_price from price_tiers where plan in ('enterprise', 'starter')) select id, plan, effective_from, avg_tier_price, row_number() over w_ordered seq_no, ntile(3) over (order by lowest_price, id) lowest_price_bucket, percent_rank() over (partition by plan order by entry_price desc nulls last) entry_price_percent_rank from unpacked window w_ordered as (partition by plan order by effective_from desc, id);
